/**
 * Fake pusher-js: records subscriptions and bindings; a test fires an event with
 * `channel.__emit(event, data)`. Instances are collected in `Pusher.__instances`.
 */
class Channel {
    constructor(name) {
        this.name = name;
        this.handlers = {};
    }
    bind(event, handler) {
        (this.handlers[event] = this.handlers[event] || []).push(handler);
    }
    unbind(event) {
        delete this.handlers[event];
    }
    unbind_all() {
        this.handlers = {};
    }
    __emit(event, data) {
        for (const handler of this.handlers[event] || []) {
            handler(data);
        }
    }
}

class Pusher {
    constructor(key, options) {
        this.key = key;
        this.options = options;
        this.channels = {};
        this.disconnected = false;
        Pusher.__instances.push(this);
    }
    subscribe(name) {
        this.channels[name] = this.channels[name] || new Channel(name);
        return this.channels[name];
    }
    disconnect() {
        this.disconnected = true;
    }
}
Pusher.__instances = [];

module.exports = Pusher;
module.exports.default = Pusher;
